sections.content:
ProgressTimelineWidget {
    width: 100%;
    height: auto;
    padding: 0 1;
    margin: 0 0 1 0;
    background: $surface;
    border: solid $border;
}

ProgressTimelineWidget > .progress-timeline-header {
    width: 100%;
    height: auto;
    text-style: bold;
    color: $text;
}

ProgressTimelineWidget > .progress-timeline-body {
    width: 100%;
    height: auto;
    color: $text;
    padding: 0 0 0 1;
}
